const esc = value => String(value ?? '').replace(/[&<>"]/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[char]));
const statusDisplayNames = Object.freeze({ COOLDOWN_EXTENSION: '【強奪】', ATTACK_DAMAGE_DOWN: '攻撃ダメージ低下', POISON: '毒', BURN: '火傷', TARGET_RESTRICTION: '対象制限' });
const statusDisplayName = value => statusDisplayNames[value] || value;
const playerFacingText = value => Object.entries(statusDisplayNames).reduce((text, [key, label]) => text.replaceAll(key, label), String(value ?? ''));
const narrativeText = value => esc(playerFacingText(value)).replace(/\\*\\*(.+?)\\*\\*/g, '<strong>$1</strong>');
const NARRATIVE_LINES_PER_STEP = 2;
const narrativeBlocks = lines => Array.isArray(lines?.[0]) ? lines : Array.from({ length: Math.ceil((lines?.length || 0) / NARRATIVE_LINES_PER_STEP) }, (_, index) => lines.slice(index * NARRATIVE_LINES_PER_STEP, (index + 1) * NARRATIVE_LINES_PER_STEP));
const narrativeLineKind = value => {
  const line = String(value ?? '').trim();
  if (/^──.+──$/.test(line)) return 'rule';
  if (/^[「『]/.test(line)) return 'dialogue';
  if (/^(――|—{2,}|＜|【)/.test(line)) return 'announcement';
  return 'narration';
};
const narrativeBlockHtml = block => (Array.isArray(block) ? block : [block]).map(line => `<span class="narrative-line ${narrativeLineKind(line)}">${narrativeText(line)}</span>`).join('');
const narrativeParagraphs = (lines, step, attributes = '') => narrativeBlocks(lines).map((block, index) => {
  const current = index === step - 1;
  return `<p class="narrative-block ${current ? 'is-current' : 'is-read'}" ${current ? 'aria-live="polite"' : ''} ${attributes} ${index >= step ? 'hidden' : ''}>${narrativeBlockHtml(block)}</p>`;
}).join('');
const categoryName = value => ({ attack: '攻撃', defense: '防御', support: '補助', heal: '回復', interference: '妨害' }[value] || value);
const CURRENCY_TYPES = [['one', '壱', 1], ['two', '弐', 2], ['three', '参', 3], ['five', '伍', 5], ['seven', '漆', 7]];
